/**
 * Components API endpoints
 */
export interface ComponentProp {
    name: string;
    type: 'string' | 'number' | 'boolean' | 'array' | 'object';
    defaultValue?: unknown;
    description?: string;
}
export interface ComponentSlot {
    name: string;
    selector: string;
    defaultContent?: string;
}
export interface ComponentEvent {
    name: string;
    description?: string;
    payload?: Record<string, string>;
}
export interface CreateComponentRequest {
    name: string;
    htmlContent: string;
    description?: string;
    props?: ComponentProp[];
    slots?: ComponentSlot[];
    events?: ComponentEvent[];
    cssImports?: string[];
}
export interface CreateComponentResponse {
    componentId: string;
    nodeId: string;
    name: string;
    projectUrl: string;
    previewUrl: string;
}
export interface ListComponentItem {
    id: string;
    name: string;
    description: string | null;
    version: number;
}
export interface ListComponentsResponse {
    projectId: string;
    components: ListComponentItem[];
}
export interface UpdateComponentRequest {
    name?: string;
    htmlContent?: string;
    description?: string;
    props?: ComponentProp[];
    slots?: ComponentSlot[];
    events?: ComponentEvent[];
    cssImports?: string[];
}
export interface UpdateComponentResponse {
    componentId: string;
    name: string;
    version: number;
    previewUrl: string;
}
/**
 * Create a new component in a project
 */
export declare function createComponent(projectId: string, data: CreateComponentRequest): Promise<CreateComponentResponse>;
/**
 * List all components in a project
 */
export declare function listComponents(projectId: string): Promise<ListComponentsResponse>;
/**
 * Update an existing component
 */
export declare function updateComponent(componentId: string, data: UpdateComponentRequest): Promise<UpdateComponentResponse>;
